method.pseudocode:
for event in event_stream:
    queue.append(render(event))
    recall_storage.write(event)

    if prompt_tokens(queue, working_context) > warning_threshold:
        queue.append(system_memory_pressure_warning())

    while true:
        output = llm(system_instructions, working_context, queue)
        if output.is_memory_function():
            result = execute_memory_function(output)
            queue.append(result)
            if output.request_heartbeat:
                continue
        else:
            recall_storage.write(output)
            send_to_user(output)
        break

    if prompt_tokens(queue, working_context) > flush_threshold:
        evicted = queue.flush_old_messages()
        recall_storage.write(evicted)
        queue.summary = summarize(queue.summary, evicted)
